values ('chengdu-research-base', '成都大熊猫繁育研究基地', 'Chengdu Research Base of Giant Panda Breeding', 'CN', '{"kind":"breeding_center","summary":{"zh":"1987 年由成都市政府建立，集大熊猫迁地保护、科研繁育、科普教育和文化旅游于一体，占地约 3.07 平方公里，也繁育小熊猫等中国特有濒危动物。","en":"Founded by the Chengdu city government in 1987, the base combines ex-situ conservation, breeding research, education and tourism on about 3.07 square kilometres, and also breeds red pandas and other endangered species native to China."},"websiteUrl":"https://www.panda.org.cn/","verifiedOn":"2026-10-23","sourceUrls":["https://www.panda.org.cn/","https://en.wikipedia.org/wiki/Chengdu_Research_Base_of_Giant_Panda_Breeding"]}'::jsonb)
