  visit_guide = '{"address":{"zh":"四川省成都市成华区熊猫大道 1375 号","en":"1375 Panda Avenue, Chenghua District, Chengdu, Sichuan"},"tips":[{"topic":"getting_there","text":{"zh":"距市中心天府广场约 10 公里，距双流国际机场约 30 公里，距天府国际机场约 70 公里。","en":"About 10 km from Tianfu Square in the city centre, 30 km from Shuangliu airport and 70 km from Tianfu airport."}},{"topic":"good_to_know","text":{"zh":"开放时间和门票以基地官网公告为准。","en":"Check the base''s official website for current opening hours and tickets."}}],"verifiedOn":"2026-10-23","sourceUrls":["https://www.panda.org.cn/"]}'::jsonb,
